// Authors and Estedad by Amin Abedi, via @fontsource 5.3.0.
// Served from /fonts/* on our own origin so the CSP keeps font-src 'self' and no third party sees visitors.
export const fonts={
 'vazirmatn-arabic.woff2':'',
 'vazirmatn-latin.woff2':'',
 'estedad-arabic.woff2':'',
};
const bin={};
export function fontResponse(name){const b64=fonts[name];if(!b64)return null;if(!bin[name])bin[name]=Uint8Array.from(atob(b64),c=>c.charCodeAt(0));return new Response(bin[name],{headers:{'Content-Type':'font/woff2','Cache-Control':'public,max-age=31536000,immutable','Access-Control-Allow-Origin':'*'}})}
